/// Pagination options using cursor tokens
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum MessageSortDirection {
    SortUnspecified = 0,
    /// Default: newest messages first (descending by time)
    SortNewestFirst = 1,
    /// Sort by oldest first (ascending by time)
    SortOldestFirst = 2,
}
impl MessageSortDirection {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            MessageSortDirection::SortUnspecified => "SORT_UNSPECIFIED",
            MessageSortDirection::SortNewestFirst => "SORT_NEWEST_FIRST",
            MessageSortDirection::SortOldestFirst => "SORT_OLDEST_FIRST",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "SORT_UNSPECIFIED" => Some(Self::SortUnspecified),
            "SORT_NEWEST_FIRST" => Some(Self::SortNewestFirst),
            "SORT_OLDEST_FIRST" => Some(Self::SortOldestFirst),
            _ => None,
        }
    }
}
